sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float angle;
uniform float center;
uniform float mode;

half4 main(float2 coord) {
    float a = radians(angle);
    float2 o = float2(cos(a), sin(a)) * size * (strength / 8.0);
    float k = floor(center + 0.5);
    float2 sr = k < 0.5 ? float2(0.0) : o;
    float2 sg = k < 0.5 ? o : (k < 1.5 ? float2(0.0) : -o);
    float2 sb = k < 1.5 ? -o : float2(0.0);
    half4 r = image.eval(coord - sr);
    half4 g = image.eval(coord - sg);
    half4 b = image.eval(coord - sb);
    half ac = k < 0.5 ? r.a : (k < 1.5 ? g.a : b.a);
    half3 rgb = half3(r.r, g.g, b.b);
    float m = floor(mode + 0.5);
    if (m < 0.5) return half4(rgb, ac);
    if (m < 1.5) return half4(rgb, max(r.a, max(g.a, b.a)));
    if (m < 2.5) {
        half lo = min(r.a, min(g.a, b.a));
        half3 un = half3(r.a > 0.001 ? r.r / r.a : 0.0, g.a > 0.001 ? g.g / g.a : 0.0, b.a > 0.001 ? b.b / b.a : 0.0);
        return half4(un * lo, lo);
    }
    return half4(rgb, clamp(max(ac, dot(rgb, half3(0.2126, 0.7152, 0.0722))), 0.0, 1.0));
}
